BEGIN TRANSACTION;
CREATE TABLE "code_sessions" (session_id VARCHAR NOT NULL, session_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, session_data JSON, agent_data JSON, team_data JSON, workflow_data JSON, metadata JSON, summary JSON, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (session_id));
INSERT INTO "code_sessions" VALUES('s1','agent','code',NULL,NULL,NULL,'{"session_state": {}}',NULL,NULL,NULL,'null',NULL,1750000000,1750000000);
CREATE TABLE code_sessions_compacted_runs (id INTEGER PRIMARY KEY, compaction_id INTEGER NOT NULL REFERENCES code_sessions_compactions(id) ON DELETE CASCADE, session_id TEXT NOT NULL, run_id TEXT NOT NULL, run_type TEXT, event_ids TEXT NOT NULL, seen_event_ids TEXT NOT NULL DEFAULT '[]', run_data TEXT, UNIQUE(session_id, run_id));
INSERT INTO "code_sessions_compacted_runs" VALUES(1,1,'s1','c0','agent','["$c0", "$read-by-c0"]','["$c0"]','{"run_id": "c0", "agent_id": "code", "session_id": "s1", "content": "answer c0", "created_at": 1750000000, "status": "COMPLETED", "messages": [{"id": "01000000-0000-0000-0000-00000000001c", "content": "question c0", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1750000000}], "metadata": {"matrix_event_id": "$c0", "matrix_seen_event_ids": ["$c0"]}}');
INSERT INTO "code_sessions_compacted_runs" VALUES(2,2,'s1','o0','agent','["$o0", "$read-by-o0"]','["$o0"]','{"run_id": "o0", "agent_id": "other", "session_id": "s1", "content": "answer o0", "created_at": 1750000000, "status": "COMPLETED", "messages": [{"id": "01000000-0000-0000-0000-00000000001d", "content": "question o0", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1750000000}], "metadata": {"matrix_event_id": "$o0", "matrix_seen_event_ids": ["$o0"]}}');
CREATE TABLE code_sessions_compactions (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES code_sessions(session_id) ON DELETE CASCADE, scope_key TEXT NOT NULL, summary TEXT, summary_model TEXT, legacy INTEGER NOT NULL DEFAULT 0, legacy_event_ids TEXT, created_at INTEGER NOT NULL);
INSERT INTO "code_sessions_compactions" VALUES(1,'s1','agent:code','code summary','summary-model',0,'[]',1750000000);
INSERT INTO "code_sessions_compactions" VALUES(2,'s1','agent:other','other summary','summary-model',0,'[]',1750000000);
CREATE TABLE "code_sessions_runs" (run_id VARCHAR NOT NULL, session_id VARCHAR NOT NULL, run_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, parent_run_id VARCHAR, status VARCHAR, run_index BIGINT, run_data JSON NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (run_id), FOREIGN KEY(session_id) REFERENCES "code_sessions" (session_id) ON DELETE CASCADE);
INSERT INTO "code_sessions_runs" VALUES('c1','s1','agent','code',NULL,NULL,NULL,NULL,'COMPLETED',0,'{"run_id": "c1", "agent_id": "code", "session_id": "s1", "content": "answer c1", "created_at": 1750000000, "status": "COMPLETED", "messages": [{"id": "01000000-0000-0000-0000-00000000001a", "content": "question c1", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1750000000}], "metadata": {"matrix_event_id": "$c1", "matrix_seen_event_ids": ["$c1"]}}',1750000000,1750000000);
INSERT INTO "code_sessions_runs" VALUES('o1','s1','agent','other',NULL,NULL,NULL,NULL,'COMPLETED',1,'{"run_id": "o1", "agent_id": "other", "session_id": "s1", "content": "answer o1", "created_at": 1750000000, "status": "COMPLETED", "messages": [{"id": "01000000-0000-0000-0000-00000000001b", "content": "question o1", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1750000000}], "metadata": {"matrix_event_id": "$o1", "matrix_seen_event_ids": ["$o1"]}}',1750000000,1750000000);
CREATE TABLE "code_sessions_usage" (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "code_sessions"(session_id) ON DELETE CASCADE, run_id TEXT, usage_data TEXT, UNIQUE(session_id, run_id));
CREATE INDEX "idx_code_sessions_session_type" ON "code_sessions" (session_type);
CREATE INDEX "idx_code_sessions_created_at" ON "code_sessions" (created_at);
CREATE INDEX "idx_code_sessions_runs_session_id" ON "code_sessions_runs" (session_id);
CREATE INDEX "idx_code_sessions_runs_run_type" ON "code_sessions_runs" (run_type);
CREATE INDEX "idx_code_sessions_runs_agent_id" ON "code_sessions_runs" (agent_id);
CREATE INDEX "idx_code_sessions_runs_team_id" ON "code_sessions_runs" (team_id);
CREATE INDEX "idx_code_sessions_runs_workflow_id" ON "code_sessions_runs" (workflow_id);
CREATE INDEX "idx_code_sessions_runs_user_id" ON "code_sessions_runs" (user_id);
CREATE INDEX "idx_code_sessions_runs_status" ON "code_sessions_runs" (status);
CREATE INDEX "idx_code_sessions_runs_created_at" ON "code_sessions_runs" (created_at);
CREATE INDEX "idx_code_sessions_runs_session_id_run_index" ON "code_sessions_runs" (session_id, run_index);
COMMIT;
